def doesAliceWin(s: str) -> bool:
    # Define the set of vowels
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Check if any character in s is a vowel
    for c in s:
        if c in vowels:
            return True

    # No vowels found, Alice cannot make a move
    return False
